    /**
     * 根据不同窗口计算最大页码值
     * @returns {Number} maxPage
     * - (28 + 16) * 2 上下页按钮宽度加margin
     * + 10 last child no margin
     * / (24 + 10) each child width + margin
     */
    function calculateMaxPage() {
        var listWrapper = $('.message-carousels-container').find('.pagerWrapper').width();
        var maxPage = ~~(((listWrapper - (28 + 16) * 2) + 10) / (24 + 10));
        return Math.min(maxPage, MAX_PAGE_DEFAULT);
    }

    /**
     * 初始化分页器
     * @param el 容器节点
     * @param pageNum 单个翻页器的页码
     */
    function initPager(el, pageNum, datasource) {
        // console.log('datasource', datasource)
        var messageCards = $(el).find('.message-cards');
        messageCards.find('.pager').html('')

        var rows = messageCards.data('rows');
        var columns = messageCards.data('columns');
        var pageSize = rows * columns;
        var totalPage = Math.ceil(datasource.length / pageSize);
        pageNum = Math.max(Math.min(pageNum, totalPage), 1);

        renderPagerUI(el, pageNum, totalPage);
        renderCardsList(el, pageNum, pageSize, datasource);
        bindPageEvents(el, pageNum, totalPage, datasource);
    }

    /**
     * 渲染分页器
     * @param el 容器节点
     * @param pageNum 单个翻页器的页码
     * @param totalPage 总页数
     */
    function renderPagerUI(el, pageNum, totalPage) {
        var messageCards = $(el).find('.message-cards');
        var messageCardsTitleEle = $(el).find('.marketing .title');
        var pageEventTrackObj = getPageEventTrackObj(messageCardsTitleEle);
        var preButton = "<a class='preButton prevOrNext'></a>";
        var nextButton = "<a class='nextButton prevOrNext'></a>";
        var totalLoopNum = Math.ceil(totalPage / maxPage)
        var loopByPageNum = Math.ceil(pageNum / maxPage)
        var paginationHtmlStr = ''
        var start,
            end,
            paginationAllList = [],
            paginationRealList = [];
        for (var i = 1; i <= totalPage; i++) {
            paginationAllList.push(i);
        }
        if (totalLoopNum === loopByPageNum && loopByPageNum !== 1) {
            end = pageNum
        } else {
            end = Math.ceil(pageNum / maxPage) * maxPage
        }
        start = end - (maxPage - 1)
        // end = Math.ceil(pageNum / maxPage) * maxPage;
        // start = end - (maxPage - 1);
        paginationRealList = paginationAllList.slice(start - 1, end);
        // console.log('pageNum1111', pageNum);
        for (var i = 0; i <= paginationRealList.length - 1; i++) {
            // var targetLink = replaceUrlParam(window.location.href, 'pageNum', paginationRealList[i]);
            var targetLink = refreshRoute(el, null, paginationRealList[i]);
            pageEventTrackObj.event_parameters.content = "page_" + paginationRealList[i];
            if (pageNum === paginationRealList[i]) {
                paginationHtmlStr += "<a onClick='return false' href='" + targetLink + "' class='pagerButton'>" + paginationRealList[i] + '</a>'
            } else {
                paginationHtmlStr += "<a href='" + targetLink + "' class='pagerButton' data-click-track='" + JSON.stringify(pageEventTrackObj) + "'>" + paginationRealList[i] + '</a>'
            }
        }
        if (totalPage > 1) {
            messageCards.find('.pager').html(preButton + paginationHtmlStr + nextButton).removeClass('hide')
        }

        if (pageNum <= 1) {
            messageCards.find('a.preButton').addClass('pageBtnDisabled')
        }
        if (pageNum >= totalPage) {
            messageCards.find('a.nextButton').addClass('pageBtnDisabled')
        }
        messageCards
            .find('a.pagerButton')
            .each(function (_, ele) {
                if (+$(ele).text() === pageNum) {
                    $(ele).addClass('selected')
                }
            })
    }

    function handlePageChange(el, currentPageNum, totalPage, type, messageCardsTitleEle) {
        // console.log(currentPageNum);
        // var $currentPageBtn = $(el).find('.message-cards').find('a.pagerButton.selected');
        if ((type === 'prev' && currentPageNum === 1) || type === 'next' && +currentPageNum === totalPage) {
            return;
        }
        type === 'prev' ? currentPageNum -= 1 : currentPageNum += 1;

        var pageEventTrackObj = getPageEventTrackObj(messageCardsTitleEle);
        pageEventTrackObj.event_parameters.content = "page_" + currentPageNum;
        trackingSiperSlide.viewTrackData = pageEventTrackObj;
        window.dispatchEvent(trackingSiperSlide);

        // var targetLink = replaceUrlParam(window.location.href, 'pageNum', currentPageNum);
        var targetLink = refreshRoute(el, null, currentPageNum);
        location.href = targetLink;
    }

