(function () {
	var kspCarouselComps = $('.ksp-carousel-comp');
	if (kspCarouselComps.length === 0) {
		return;
	}
	var kspCarouselSwiper = [];
	function init() {
		$.each(kspCarouselComps, function (index, kspCarouselItem) {
			/**
			 * swiper 初始化
			 */
			var swiperSlides = $(kspCarouselItem).find('.swiper-slide');
			var swiperContainerTarget = $(kspCarouselItem).find('.swiper');
			var swiperWrapper = $(kspCarouselItem).find('.swiper-wrapper');
			swiperContainerTarget.addClass('ksp-carousel-swiper' + index);
			swiperContainerTarget.attr('data-index', index);
			swiperSlides.length > 1
				? (kspCarouselSwiper[index] = new Swiper('.ksp-carousel-swiper' + index, {
						autoplay: false, //可选选项，自动滑动
						preventClicks: true,
						loop: false,
						dotLimit: 5,
						threshold: 10,
						pagination: {
							el: '.swiper-pagination ',
							clickable: true,
						},
						on: {
							paginationRender: function () {
								this.translateValue = 0;
								renderCustomBullets(this.$el, this.params.dotLimit);
							},
							slideChange: function (swiper) {
								var swiperSlide = $(swiper.slides[this.previousIndex]);
								var videoSlide = swiperSlide.find('.ksp-carousel-video video');
								videoSlide.length && !videoSlide[0].paused && videoSlide[0].pause();
								setCustomPageBullets(this, this.params.dotLimit);
							},
						},
					}))
				: swiperWrapper.addClass('no-swiper');
		});
		/**
		 * 视频
		 */
		var videoArr = $('.ksp-carousel-video');

		if (videoArr.length == 0) {
			return;
		}
		function touchEventHandle(e) {
			if (e.target.nodeName === 'VIDEO') {
				if (this.paused()) {
					this.play();
				} else {
					this.pause();
				}
			}
		}
		function playEventHandle() {
			var _t = this;
			var bigPlayButtonEl = $(this.bigPlayButton.el_);
			bigPlayButtonEl.addClass('animation');
			_t.bigPlayButton.show();
			setTimeout(function () {
				bigPlayButtonEl.removeClass('animation');
				_t.bigPlayButton.hide();
			}, 1000);
		}

		_.forEach(videoArr, function (videoEl) {
			var videoObj = videojs(videoEl.id);
			videoObj.on('touchstart', touchEventHandle);
			videoObj.on('play', playEventHandle);
			videoObj.on('pause', playEventHandle);
		});
	}
	init();
})();

