(function () {
	var showcaseCardTabComponents = $('.showcase-card-tab-container');
	if (showcaseCardTabComponents.length === 0) {
		return;
	}
	var showcaseCardSwiper = [];
	var tabWidth = $('.showcase-card-tab-container').width(); // 容器宽度
	var tabSlides = $('.showcase-card-tab-container .swiper-slide');
	var trackingSiperSlide = new CustomEvent('tracking-swiper-slide');
	var dialogCardEle = '.card';
	var popupDialogEle = '.dialog-element-box, .popup-panel.mobile-link';
	/**
	 * 计算视窗尺寸
	 */
	function calculateWindowSize() {
		tabWidth = $('.showcase-card-tab-container').width();
		// 初始化宽度
		tabSlides.each(function (index, tab) {
			$(tab).css({
				width: tabWidth + 'px',
			});
		});
	}

	function toggleTabItem(target) {
		var parent=target.parents('.tab-list');
		var offsetX=target[0].offsetLeft - parent[0].clientWidth / 2+ target[0].clientWidth/ 2 ;
		target.addClass('active');
		parent.scrollLeft(offsetX);
		target.siblings().removeClass('active');
		target.addClass('active');
	}
	
	/**
	 * 标签点击
	 */
	$('.showcase-card-tab-container .tab-item').on('click', function () {
		var index = this.dataset.index;
		var tarSwiperIndex = $(this).parent().parent().parent().parent().find('.swiper').attr('data-index');
		toggleTabItem($(this));
		showcaseCardSwiper[tarSwiperIndex].slideTo(index, 1000, false);
	});
	/**
	 * 弹窗点击
	 */
	$('.showcase-card-tab-container .column').on('click', dialogCardEle + ',' + popupDialogEle, function(event) {
			if(this.classList.contains('has-popup-mobile')){
					event.preventDefault();
					return;
			} 
			var target = $(event.currentTarget);
			var dialogId = target.attr('data-dialog-id');
			if(dialogId) {
					event.preventDefault();
					if(window.openPopDialog) {
							window.openPopDialog(dialogId);
					}
			}
			if($(this).is(popupDialogEle)) {
					event.stopPropagation();
			}
	});

	function init() {
		$.each(showcaseCardTabComponents, function (index, tabComp) {
			var swiperSlides = $(tabComp).find('.swiper-slide');
			var swiperContainerTarget = $(tabComp).find('.swiper');
			var trackElementContainer = $(tabComp).find('.track-view-element-container');
			var afterTrackingViewEle = [];
			swiperContainerTarget.addClass('showcase-card-swiper' + index);
			swiperContainerTarget.attr('data-index', index);
			swiperSlides.length > 1 &&
				(showcaseCardSwiper[index] = new Swiper('.showcase-card-swiper' + index, {
					autoplay: false, //可选选项，自动滑动
					loop: false,
					preventClicks: true,
					threshold: window.screenInfo.width > 834 ? 100 : 10,
					on: {
						slideChangeTransitionStart: function (event) {
							var targetSwipe = $(event.$el);
							var eventDom = targetSwipe.parent().find('.tab-item').eq(this.activeIndex);
							toggleTabItem(eventDom);
						},
						resize: function () {
							calculateWindowSize();
						},
						transitionEnd: function(swiper){
								var slideIndex = $(swiper.el).find('.swiper-slide-active').attr('data-slide-index');
								var dataElement = $(swiper.el).find('.swiper-slide-active .track-element-data');
								if(dataElement) {
										var eleArray = []
										dataElement.each(function(e) {
												if(dataElement[e].dataset['clickTrack'] && !afterTrackingViewEle[slideIndex]){
														eleArray.push(e);
														var dataSet = JSON.parse(dataElement[e].dataset['clickTrack']);
														dataSet.event_name = "view_promotion";
														trackingSiperSlide.swiper = dataElement[e];
														trackingSiperSlide.viewTrackData = dataSet;
														window.dispatchEvent(trackingSiperSlide);

												}
										})
										afterTrackingViewEle[slideIndex] = eleArray;
								}
						}
					}
				}));

				if(trackElementContainer.length > 0) {
						var intersectionObserver = new IntersectionObserver(function(entries) {
								entries.forEach(function(entry) {
										if (entry.isIntersecting && entry.intersectionRatio > 0) {
												var target = entry.target;
												var activeEle = $(target).find('.swiper-slide');
												var slideIndex = "0";
												var dataElement = $(target).find('.swiper-slide .track-element-data');
												if(activeEle.length > 1) {
														slideIndex = activeEle.attr('data-slide-index').toString();
														dataElement = $(target).find('.swiper-slide-active .track-element-data');
												}
												if(dataElement.length > 0){
												var eleArray = []
												dataElement.each(function(e) {
														if(dataElement[e].dataset['clickTrack'] && !afterTrackingViewEle[slideIndex]){
																var dataSet = JSON.parse(dataElement[e].dataset['clickTrack']);
																dataSet.event_name = "view_promotion";
																trackingSiperSlide.swiper = dataElement[e];
																trackingSiperSlide.viewTrackData = dataSet;
																window.dispatchEvent(trackingSiperSlide);
														}
														})
												}
												afterTrackingViewEle[slideIndex] = eleArray;

										}
								});
						});
						intersectionObserver.observe(trackElementContainer[0]);
				}
		});
	}
	init();
})();

$(function () {
    var dialogPopUp = $('.feature-dialog-container');
    if (!dialogPopUp.length) return;
    dialogPopUp.each(function () {
        $('body').append(this);
    });

    var openPopDialog = function (dialogId) {
        var matchingEle = $('body').find('#' + dialogId);
        if (matchingEle.length > 0) {
            var closeIcon = matchingEle.find('.close-icon');
            var dialogRichText = matchingEle.find('.dialog-rich-text');
            $('body').addClass('popup-dialog-body-style');
            matchingEle.addClass('is-open');
            setTimeout(function () {
                matchingEle.addClass('active');
            }, 0)
            closeIcon.off('click').on('click', function () {
                matchingEle.removeClass('active');
                $('body').removeClass('popup-dialog-body-style');
                setTimeout(function () {
                    dialogRichText.scrollTop(0);
                    matchingEle.removeClass('is-open');
                }, 400)
            })
        }
    }
    window.openPopDialog = openPopDialog;
});
(function () {

	function lazyLoadVideo(e) {
		var elem = e.data;
		if(!$(elem).hasClass('video-specific-to-classic-video')) return;
		var uniqueId = $(elem).data('unique-id');
		var container = $('#' + uniqueId + '.classic-video-container');
		if(!container.length) return;
		var propertyStr = $(elem).attr('property');
		var property = propertyStr ? JSON.parse(propertyStr) : {};
		var options = getOptions(elem);
		if (property.videoType === 'youtube' && window.TclConsent && !window.TclConsent.allowPlugin('youtube')) {
			window.TclConsent.applyYoutubeFallback(options, property.youtubeVideoSource);
		}
		var player = videojs(elem, options);
		player.on('init', function() {
			var parent = container.children('.lazy_load_video_wrap');
			parent.removeClass('lazy_load_video_wrap');
			parent.siblings('style').remove();
			parent.siblings('picture').remove();
		});
		player.on("playing", videoPlayTrack);
		player.on("pause", videoPauseTrack);
	}

	function getSrc(property, videoSource) {
		var src = videoSource;
		switch(property.videoType) {
			case 'youtube':
				src = property.youtubeVideoSource;
				break;
			case 'bilibili':
				src = property.bilibiliVideoSource;
				break;
			default:
				break;
		}
		return src;
	}

	function getType(property) {
		var type = property.videoNormalType;
		switch(property.videoType) {
			case 'youtube':
				type = 'video/youtube';
				break;
			case 'bilibili':
				type = 'video/bilibili';
				break;
			default:
				break;
		}
		return type;
	}

	function getMode(property, videoMode) {
		var mode = videoMode;
		switch(property.videoType) {
			case 'youtube':
				mode = property.youtubeVideoMode;
				break;
			case 'bilibili':
				mode = property.bilibiliVideoMode;
				break;
			default:
				break;
		}
		return mode;
	}


	function getOptions(videoEl) {
		var rtl = $('html').hasClass('rtl');
		var propertyStr = $(videoEl).attr('property');
		var property = JSON.parse(propertyStr);
		var desktop = window.innerWidth >= 835;
		var isMobileHorizontalAlign = property.posterMobileHorizontalAlign ? property.posterMobileHorizontalAlign : property.posterHorizontalAlign;
		var isMobileVerticalAlign = property.posterMobileVerticalAlign ? property.posterMobileVerticalAlign : property.posterVerticalAlign;
		var videoSource = (desktop || property.mobileVideoSource === '') ? property.desktopVideoSource : property.mobileVideoSource;
		var videoMode = desktop ? property.desktopVideoMode : property.mobileVideoMode;
		var src = getSrc(property, videoSource);
		var type = getType(property);
		var mode = getMode(property, videoMode);
		var controls = property.videoType === 'normal';
		var textAlign = desktop ? property.posterHorizontalAlign : isMobileHorizontalAlign;
		var justifyMap = { left: 'flex-start', center: 'center', right: 'flex-end' };
		var rtlJustifyMap = { left: 'flex-end', center: 'center', right: 'flex-start' };
		var rtlJustifyMapFlex = desktop ? rtlJustifyMap[property.posterHorizontalAlign] : rtlJustifyMap[isMobileHorizontalAlign];
		var justifyContent = rtl ? rtlJustifyMapFlex: justifyMap[textAlign];
		var alignMap = { top: 'flex-start', center: 'center', bottom: 'flex-end' };
		var alignItems = desktop ? alignMap[property.posterVerticalAlign] : alignMap[isMobileVerticalAlign];
		var posterSource = desktop ? property.desktopPosterSource : property.mobilePosterSource;
		var posterType = property.posterType === 'video' ? 'clip' : property.posterType;
		var posterImage = posterType === 'image' ? posterSource : '';
		var posterVideo = posterType === 'clip' ? posterSource : '';
		var bottomText = property.posterButtonText? property.posterButtonText: 'Play video';
		var richText = desktop ? property.richTextContent : property.richForMobile;
		var options = {
			sources: [
				{
					src: src,
					type: type,
				},
			],
			loop: property.loop,
			controls: controls,
			controlBar: {
				children: [
					'playToggle',
					'CurrentTimeDisplay',
					'TimeDivider',
					'DurationDisplay',
					'CustomControlSpacer',
					'VolumePanel',
					'RotateToggle',
					'FullscreenToggle',
					'ProgressControl',
				],
			},
			youtube: { ytControls: 1 },
			plugins: {
				tclPlayer: {
					autoplay: property.autoplay,
					layout: property.layout,
					type: property.videoType,
					mode: mode === 'default' ? '' : mode,
					inactivityTimeout: !desktop,
					errorMessage: property.errorMessage,
					bgTheme: 'unset',
					cover: {
						title: property.posterTitle,
						heading: property.posterHeading || 'h2',
						subtitle: property.posterDesc,
						button: bottomText,
						learnMoreLinkText: property.linkLabel,
						learnMoreLink: property.posterLink,
						textAlign: textAlign,
						justifyContent: justifyContent,
						alignItems: alignItems,
						theme: property.posterTheme,
						animate: property.animate,
						target: property.target,
						nofollow: property.nofollow,
						description: richText,
						learnMoreEventTrack: property.learnMoreEventTrack,
						poster: {
							type: posterType,
							image: posterImage,
							alt: property.posterAlt,
							video: posterVideo
						},
					},
				},
			},
		};
		return options;
	}

	function videoPlayTrack () {
		var _this = this;
		var videoUrl = _this.currentSrc();
		var fileName = videoUrl.split('/').pop();
		var property = JSON.parse(_this.options_.property);
		var posterTitle = property.posterTitle;
		var trackingVideo = new CustomEvent('tracking-play-video');
		trackingVideo.videoSrc = videoUrl;
		trackingVideo.posterTitle = posterTitle ? posterTitle: fileName;
		window.dispatchEvent(trackingVideo);
	}

	function videoPauseTrack () {
		var _this = this;
		var videoUrl = _this.currentSrc();
		var fileName = videoUrl.split('/').pop();
		var videoDuration = _this.duration() ?	_this.duration() : 0;
		var property = JSON.parse(_this.options_.property);
		var posterTitle = property.posterTitle;
		var trackingVideo = new CustomEvent('tracking-over-video');
		trackingVideo.videoSrc = videoUrl;
		trackingVideo.videoDuration = videoDuration;
		trackingVideo.posterTitle = posterTitle ? posterTitle: fileName;
		window.dispatchEvent(trackingVideo);
	}

	window.addEventListener('lazyload-video', lazyLoadVideo);

})();

